INSERT INTO public.gas_station_recommendation (id, tenant_id, station_id, recommendation_date, category, title, detail, estimated_impact_usd, priority, confidence_pct, explanation, status, owner_feedback, source_model_run_id, created_at, updated_at) VALUES (1, 'demo_gas_station_001', 1, '2026-07-04', 'FUEL_PRICING', 'Raise premium fuel by 3 cents', 'Competitors within 2 miles moved up overnight; demand elasticity is low on premium.', 182.00, 1, 88.00, 'Three tracked competitor stations raised premium 3-5c after the wholesale rack price increase. Your premium volume is only 9% of gallons, so the price move protects margin with minimal volume risk.', 'NEW', NULL, 'run_seed_demo_001', '2026-07-04 00:15:58.113887+00', '2026-07-04 00:15:58.113887+00');
INSERT INTO public.gas_station_recommendation (id, tenant_id, station_id, recommendation_date, category, title, detail, estimated_impact_usd, priority, confidence_pct, explanation, status, owner_feedback, source_model_run_id, created_at, updated_at) VALUES (2, 'demo_gas_station_001', 1, '2026-07-04', 'ORDERING', 'Order 24 fewer gallons of whole milk', 'Demand trending down 11% over 3 weeks; current par level causes expiry write-offs.', 96.00, 2, 82.00, 'Whole milk unit sales fell three consecutive weeks while 2% held steady. Cutting the standing order avoids the spoilage pattern seen the past two Fridays.', 'NEW', NULL, 'run_seed_demo_001', '2026-07-04 00:15:58.113887+00', '2026-07-04 00:15:58.113887+00');
INSERT INTO public.gas_station_recommendation (id, tenant_id, station_id, recommendation_date, category, title, detail, estimated_impact_usd, priority, confidence_pct, explanation, status, owner_feedback, source_model_run_id, created_at, updated_at) VALUES (3, 'demo_gas_station_001', 1, '2026-07-04', 'STAFFING', 'Schedule your faster cashier for the 4-8 PM rush', 'Transaction speed and void rate differ materially between shift options.', 65.00, 3, 74.00, 'POS data shows a 19% faster average transaction and half the void rate for the suggested staffing option during peak hours.', 'NEW', NULL, 'run_seed_demo_001', '2026-07-04 00:15:58.113887+00', '2026-07-04 00:15:58.113887+00');
INSERT INTO public.gas_station_recommendation (id, tenant_id, station_id, recommendation_date, category, title, detail, estimated_impact_usd, priority, confidence_pct, explanation, status, owner_feedback, source_model_run_id, created_at, updated_at) VALUES (4, 'demo_gas_station_001', 2, '2026-07-04', 'MAINTENANCE', 'Freezer compressor showing early warning signs', 'Compressor duty cycle rising ~9 days before typical failure profile.', 1450.00, 1, 71.00, 'Duty-cycle telemetry matches the pre-failure signature from two prior freezer failures across your stores. A scheduled inspection is far cheaper than emergency repair plus product loss.', 'NEW', NULL, 'run_seed_demo_001', '2026-07-04 00:15:58.113887+00', '2026-07-04 00:15:58.113887+00');
INSERT INTO public.gas_station_recommendation (id, tenant_id, station_id, recommendation_date, category, title, detail, estimated_impact_usd, priority, confidence_pct, explanation, status, owner_feedback, source_model_run_id, created_at, updated_at) VALUES (5, 'demo_gas_station_001', NULL, '2026-07-04', 'ANOMALY', 'Hilltop Express shows suspicious cash shortages', 'Reconciliation gaps on 4 of the last 6 evening shifts at ST-003 exceed 3x the chain baseline.', 620.00, 1, 79.00, 'Evening shift cash-over/short at ST-003 averages -$31 versus a chain baseline of -$9. The pattern concentrates on one shift schedule; review shift reconciliations before escalating.', 'NEW', NULL, 'run_seed_demo_001', '2026-07-04 00:15:58.113887+00', '2026-07-04 00:15:58.113887+00');
